<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Models\{Feeling,FeelingExpression,FeelingCause,CopingMechanism}; use App\Support\ApiResponse;
class LookupController extends Controller {use ApiResponse; public function feelings(){return response()->json(['feelings'=>Feeling::where('is_active',1)->with(['expressions'=>fn($q)=>$q->where('is_active',1)->orderBy('sort_order')])->orderBy('sort_order')->get()]);} public function expressions(){return response()->json(['expressions'=>FeelingExpression::where('is_active',1)->with('feeling:id,name')->orderBy('sort_order')->get()]);} public function causes(){return response()->json(['causes'=>FeelingCause::where('is_active',1)->orderBy('sort_order')->get()]);} public function coping(){return response()->json(['coping_mechanisms'=>CopingMechanism::where('is_active',1)->orderBy('sort_order')->get()]);}}
